// Builds the diagram script that artifact origins serve at `/__portifact/diagrams.<version>.js`:
// the pinned Mermaid build (its single-file `mermaid.min.js`, no chunks to load) followed by
// Portifact's runner (`src/browser`). The version is derived from the script's bytes, so its URL
// can be cached as immutable. The script is compressed here, once, with brotli at its highest
// level, and written as two modules the content Worker imports: `dist/diagrams-version.js` (the
// version, small) and `dist/diagrams.js` (the brotli body as base64, loaded on first use).
import { mkdir, readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { brotliCompressSync, constants } from "node:zlib";

const root = new URL("..", import.meta.url).pathname;
const result = await Bun.build({
  entrypoints: [`${root}src/browser/entry.ts`],
  target: "browser",
  format: "iife",
  minify: true,
});
const [output] = result.outputs;
if (!result.success || !output) {
  for (const log of result.logs) console.error(log);
  process.exit(1);
}
const runner = await output.text();
const mermaidDist = dirname(Bun.resolveSync("mermaid", root));
const mermaidVersion: string = JSON.parse(
  await readFile(join(mermaidDist, "..", "package.json"), "utf8"),
).version;
// The source map is not shipped, so the comment pointing at it goes too.
const mermaid = (await readFile(join(mermaidDist, "mermaid.min.js"), "utf8")).replace(
  /\n\/\/# sourceMappingURL=\S+\s*$/,
  "\n",
);
// Mermaid has a few non-ASCII characters, all in regular expressions, where a \u escape means
// the same. Escaping them keeps the script ASCII, so the Worker holds it as a one-byte string.
const joined = `${mermaid}\n${runner}`;
// After a backslash the escape would change meaning; no build has one, so refuse rather than guess.
if (/\\[\u0080-\uffff]/.test(joined)) throw new Error("Escaped non-ASCII character in the script");
const script = joined.replace(
  /[\u0080-\uffff]/g,
  (char) => `\\u${char.charCodeAt(0).toString(16).padStart(4, "0")}`,
);
const digest = new Bun.CryptoHasher("sha256").update(script).digest("hex").slice(0, 16);
const bytes = Buffer.from(script, "utf8");
const brotli = brotliCompressSync(bytes, {
  params: {
    [constants.BROTLI_PARAM_QUALITY]: constants.BROTLI_MAX_QUALITY,
    [constants.BROTLI_PARAM_SIZE_HINT]: bytes.length,
  },
});
await mkdir(`${root}dist`, { recursive: true });
const header = "// Generated by packages/render/scripts/build-diagrams.ts. Do not edit.\n";
await Bun.write(
  `${root}dist/diagrams-version.js`,
  `${header}export const DIAGRAM_VERSION = "${digest}";\nexport const MERMAID_VERSION = "${mermaidVersion}";\n`,
);
await Bun.write(
  `${root}dist/diagrams-version.d.ts`,
  `${header}/** 16 hex digits of the SHA-256 of the diagram script (Mermaid ${mermaidVersion} and the runner). */\nexport declare const DIAGRAM_VERSION: string;\nexport declare const MERMAID_VERSION: string;\n`,
);
await Bun.write(
  `${root}dist/diagrams.js`,
  `${header}export const DIAGRAM_BROTLI = "${brotli.toString("base64")}";\nexport const DIAGRAM_BYTES = ${bytes.length};\n`,
);
await Bun.write(
  `${root}dist/diagrams.d.ts`,
  `${header}/** The diagram script compressed with brotli, as base64. */\nexport declare const DIAGRAM_BROTLI: string;\n/** The script's uncompressed size in bytes. */\nexport declare const DIAGRAM_BYTES: number;\n`,
);
console.log(
  `diagram script: ${bytes.length} bytes, ${brotli.length} with brotli (Mermaid ${mermaidVersion}), version ${digest}`,
);
